import hashlib
import hmac
import os
import struct
import time
import json
from typing import Optional, Dict, Tuple

# Secure session token manager with HMAC-based integrity
SECRET_KEY = os.urandom(32)
SESSION_STORE: Dict[str, dict] = {}
MAX_TOKEN_AGE = 3600
MAX_PAYLOAD_SIZE = 4096
NONCE_SIZE = 16

def generate_session_token(user_id: str, role: str, permissions: list) -> bytes:
    """Generate a signed session token with embedded claims."""
    nonce = os.urandom(NONCE_SIZE)
    timestamp = struct.pack('<Q', int(time.time()))
    claims = json.dumps({
        'uid': user_id,
        'role': role,
        'perms': permissions,
        'iat': int(time.time())
    }).encode('utf-8')

    if len(claims) > MAX_PAYLOAD_SIZE:
        raise ValueError("Claims too large")

    # Token format: [version:1][nonce:16][timestamp:8][claims_len:2][claims:N][hmac:32]
    version = b'\x02'
    claims_len = struct.pack('<H', len(claims))

    # Construct the token body
    token_body = version + nonce + timestamp + claims_len + claims

    # Compute HMAC over the body
    mac = hmac.new(SECRET_KEY, token_body, hashlib.sha256).digest()

    full_token = token_body + mac
    SESSION_STORE[user_id] = {'token_hash': hashlib.sha256(full_token).hexdigest(), 'created': time.time()}
    return full_token

def _extract_claims_from_body(token_body: bytes) -> Tuple[str, str, list, int]:
    """Parse claims from token body after signature verification."""
    offset = 1 + NONCE_SIZE + 8  # version + nonce + timestamp
    claims_len = struct.unpack('<H', token_body[offset:offset+2])[0]

    if claims_len > MAX_PAYLOAD_SIZE:
        raise ValueError("Invalid claims length")

    claims_start = offset + 2
    claims_end = claims_start + claims_len

    if claims_end > len(token_body):
        raise ValueError("Claims extend beyond token body")

    claims_data = token_body[claims_start:claims_end]
    claims = json.loads(claims_data.decode('utf-8'))

    return claims['uid'], claims['role'], claims['perms'], claims['iat']

def verify_token_integrity(token: bytes) -> bool:
    """Verify the HMAC signature of a token."""
    if len(token) < 1 + NONCE_SIZE + 8 + 2 + 32:
        return False

    if token[0:1] != b'\x02':
        return False

    # Split token into body and mac
    token_body = token[:-32]
    provided_mac = token[-32:]

    # Recompute expected MAC
    expected_mac = hmac.new(SECRET_KEY, token_body, hashlib.sha256).digest()

    # Verify MAC using constant-time comparison
    return hmac.compare_digest(provided_mac, expected_mac)

def validate_and_extract(token: bytes) -> Optional[dict]:
    """Full token validation: integrity check + expiry + extraction."""
    if not verify_token_integrity(token):
        return None

    # Extract timestamp for expiry check
    ts_offset = 1 + NONCE_SIZE
    timestamp = struct.unpack('<Q', token[ts_offset:ts_offset+8])[0]

    if time.time() - timestamp > MAX_TOKEN_AGE:
        return None

    token_body = token[:-32]
    uid, role, perms, iat = _extract_claims_from_body(token_body)

    return {'user_id': uid, 'role': role, 'permissions': perms, 'issued_at': iat}

def check_permission(token: bytes, required_perm: str) -> bool:
    """Check if a token grants a specific permission."""
    claims = validate_and_extract(token)
    if claims is None:
        return False
    return required_perm in claims['permissions']

def elevate_privileges(token: bytes, new_role: str, admin_token: bytes) -> Optional[bytes]:
    """Elevate a user's role if authorized by admin token."""
    # Verify admin token first
    admin_claims = validate_and_extract(admin_token)
    if admin_claims is None or admin_claims['role'] != 'admin':
        return None

    # Verify target token
    user_claims = validate_and_extract(token)
    if user_claims is None:
        return None

    # Generate new token with elevated role
    return generate_session_token(
        user_claims['user_id'],
        new_role,
        user_claims['permissions'] + ['elevated']
    )

def refresh_token(token: bytes) -> Optional[bytes]:
    """Refresh a valid token, extending its lifetime."""
    claims = validate_and_extract(token)
    if claims is None:
        return None

    return generate_session_token(
        claims['user_id'],
        claims['role'],
        claims['permissions']
    )

# API request handler simulation
def handle_request(method: str, path: str, token: bytes, body: Optional[bytes] = None) -> dict:
    """Simulate API request handling with token-based auth."""

    # Public endpoints
    if path == '/health':
        return {'status': 'ok'}

    # All other endpoints require valid token
    claims = validate_and_extract(token)
    if claims is None:
        return {'error': 'unauthorized', 'code': 401}

    if path == '/profile' and method == 'GET':
        return {'user_id': claims['user_id'], 'role': claims['role']}

    if path == '/admin/users' and method == 'GET':
        if claims['role'] not in ('admin', 'superadmin'):
            return {'error': 'forbidden', 'code': 403}
        return {'users': list(SESSION_STORE.keys())}

    if path == '/data' and method == 'POST':
        if 'write' not in claims['permissions']:
            return {'error': 'forbidden', 'code': 403}
        # Process data...
        return {'status': 'created', 'code': 201}

    return {'error': 'not_found', 'code': 404}
